"""Clipper: y = x limited to -0.3 .. 0.3."""

import numpy as np
from gnuradio import gr


class blk(gr.sync_block):
    """Clipper: y = x limited to -0.3 .. 0.3."""

    def __init__(self):
        gr.sync_block.__init__(self, name="Clipper", in_sig=[np.float32], out_sig=[np.float32])

    def work(self, input_items, output_items):
        x = input_items[0]
        output_items[0][:] = np.clip(x, -0.3, 0.3)
        return len(output_items[0])
